// Leda 的 24kHz PCM。查天气、联网、回忆各垫一句，结果回来前不连着说。
export type AsideLine = {
  text: string;
  pcm: string;
};

export const ASIDE_BY_TOOL: Record<string, AsideLine> = {"get_weather":{"text":"嗯，我看看。","pcm":""},"web_search":{"text":"嗯，我查查。","pcm":""},"recall_memory":{"text":"嗯，我想想。","pcm":""}};

export function asideLineFor(toolName: string): AsideLine {
  return ASIDE_BY_TOOL[toolName] ?? ASIDE_BY_TOOL.recall_memory;
}
